+//
+// Call Table
+//
+
+typedef Value(*rpcfn_type)(const Array& params);
+pair<string, rpcfn_type> pCallTable[] =
+{
+    make_pair("stop",               &stop),
+    make_pair("getblockcount",      &getblockcount),
+    make_pair("getblocknumber",     &getblocknumber),
+    make_pair("getdifficulty",      &getdifficulty),
