+        m_listCtrl = m_listCtrlSentReceived;
+        fShowGenerated = false;
+        fShowSent = true;
+        fShowReceived = true;
+    }
+    else if (nPage == SENT)
+    {
+        m_listCtrl = m_listCtrlSent;
+        fShowGenerated = false;
+        fShowSent = true;
+        fShowReceived = false;
+    }
+    else if (nPage == RECEIVED)
+    {
+        m_listCtrl = m_listCtrlReceived;
+        fShowGenerated = false;
+        fShowSent = false;
+        fShowReceived = true;
+    }
+    RefreshListCtrl();
+    m_listCtrl->SetFocus();
